fn get_column(input: &Vec<Vec<i8>>, _m: usize, _n: usize, j: usize) -> Vec<i8> {
    // Assuming `input` has exactly `_n` rows and each row has at least `j+1` elements.
    let mut col = Vec::with_capacity(_n);
    for i in 0.._n {
        col.push(input[i][j]);
    }
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // `input` is an n×m matrix, i.e., `input.len() == n` and each row has length m.
    // We want its transpose, which is an m×n matrix.
    let mut result = Vec::with_capacity(m);
    for j in 0..m {
        result.push(get_column(&input, m, n, j));
    }
    result
}

// Example usage and test
fn main() {
    let mat = vec![
        vec![1, 2, 3],
        vec![4, 5, 6],
    ]; // 2×3 matrix

    let t = column_stack(mat, 3, 2);
    // t should be a 3×2 matrix: [[1,4],[2,5],[3,6]]
    assert_eq!(t, vec![
        vec![1, 4],
        vec![2, 5],
        vec![3, 6],
    ]);

    println!("Transpose computed successfully: {:?}", t);
}